# Analysis & Pre-Thinking

- **Core Requirements**: 
  - Update `ViewsMenu.vue` to display current view name
  - Add "Save As" flow for creating new named views
  - Handle view switching with confirmation if layout changed
  - Add ViewsMenu to MainMenu.vue

- **Strategic Approach**:
  1. Enhance `ViewsMenu.vue` with current view display, "Save As" dialog, and layout change detection
  2. Add confirmation modal for layout changes before switching views
  3. Integrate ViewsMenu into MainMenu.vue
  4. Update `src/store/views.js` to track layout changes and support "Save As" workflow

- **Dependencies & Risks**:
  - Need to detect layout changes reliably (compare current vs. saved layout)
  - Modal/dialog for "Save As" name input
  - Confirmation flow requires user interaction blocking
  - Store state must persist last layout snapshot for comparison

- **Target Files**:
  - `src/components/main-menu/ViewsMenu.vue` (modify)
  - `src/components/main-menu/MainMenu.vue` (modify)
  - `src/store/views.js` (modify)

---

## File 1: ViewsMenu.vue

```vue src/components/main-menu/ViewsMenu.vue
<script setup>
import {
  MenubarSub,
  MenubarSubContent,
  MenubarSubTrigger,
  MenubarPortal,
} from 'reka-ui'
import MenubarItem from './MenubarItem.vue'
import MenuDivider from './MenuDivider.vue'
</script>

<template>
  <MenubarSub>
    <MenubarSubTrigger class="w-full flex items-center gap-2 px-2 py-1 rounded cursor-pointer hover:bg-base-200">
      <i class="fa-solid fa-table-columns"></i>
      Views
      <i class="fa-solid fa-chevron-right ml-auto text-xs"></i>
    </MenubarSubTrigger>
    <MenubarPortal>
      <MenubarSubContent
        class="py-2 min-w-52 outline-none bg-base-100 rounded-lg px-2 border border-white/30 shadow-lg"
        :side-offset="8"
      >
        <!-- Current view display -->
        <div v-if="currentViewName" class="px-2 py-1 text-xs opacity-75 mb-2">
          <span class="font-semibold">Current:</span>
          <span class="ml-1 text-blue-400">{{ currentViewName }}</span>
        </div>

        <!-- Create new view (admin only) -->
        <MenubarItem v-if="isProjectAdmin" @click.stop="openCreate">
          <i class="fa-solid fa-plus"></i>
          Create new view
        </MenubarItem>

        <!-- Save current view -->
        <MenubarItem @click="openSaveAsDialog">
          <i class="fa-solid fa-floppy-disk"></i>
          Save As
        </MenubarItem>

        <!-- Update current view (if one is loaded) -->
        <MenubarItem 
          v-if="currentViewName && isProjectAdmin" 
          @click="updateCurrentView"
          class="opacity-80"
        >
          <i class="fa-solid fa-arrow-rotate-right"></i>
          Update current view
        </MenubarItem>

        <MenuDivider v-if="views.length" />

        <!-- List of saved views -->
        <div v-if="views.length" class="max-h-64 overflow-y-auto">
          <div
            v-for="view in views"
            :key="view.name"
            class="flex items-center gap-1 group"
          >
            <MenubarItem 
              class="flex-1" 
              @click="switchToView(view)"
              :class="{ 'font-bold text-blue-400': view.name === currentViewName }"
            >
              <i class="fa-regular fa-window-restore"></i>
              <span class="truncate max-w-36">{{ view.name }}</span>
            </MenubarItem>

            <!-- Edit (admin only) -->
            <button
              v-if="isProjectAdmin"
              class="opacity-0 group-hover:opacity-100 btn btn-ghost btn-xs"
              @click.stop="openEdit(view)"
              title="Edit view"
            >
              <i class="fa-solid fa-pen text-xs"></i>
            </button>

            <!-- Delete (admin only) -->
            <button
              v-if="isProjectAdmin"
              class="opacity-0 group-hover:opacity-100 btn btn-ghost btn-xs text-error"
              @click.stop="deleteView(view.name)"
              title="Delete view"
            >
              <i class="fa-solid fa-trash text-xs"></i>
            </button>
          </div>
        </div>

        <div v-else class="px-2 py-1 text-xs opacity-50">
          No saved views yet
        </div>
      </MenubarSubContent>
    </MenubarPortal>
  </MenubarSub>

  <!-- Save As Dialog -->
  <div v-if="showSaveAsDialog" class="fixed inset-0 bg-black/50 flex items-center justify-center z-50">
    <div class="bg-base-100 rounded-lg p-6 w-96 border border-white/30 shadow-lg">
      <h3 class="text-lg font-bold mb-4">Save Current View As</h3>

      <input
        v-model="saveAsName"
        type="text"
        placeholder="Enter view name"
        class="input input-bordered w-full mb-4"
        @keyup.enter="confirmSaveAs"
        ref="saveAsInput"
      />

      <div v-if="saveAsError" class="text-error text-sm mb-3">
        {{ saveAsError }}
      </div>

      <div class="flex gap-2 justify-end">
        <button class="btn btn-ghost btn-sm" @click="closeSaveAsDialog">
          Cancel
        </button>
        <button 
          class="btn btn-primary btn-sm" 
          @click="confirmSaveAs"
          :disabled="!saveAsName.trim()"
        >
          Save
        </button>
      </div>
    </div>
  </div>

  <!-- Layout Change Confirmation Dialog -->
  <div v-if="showLayoutConfirmation" class="fixed inset-0 bg-black/50 flex items-center justify-center z-50">
    <div class="bg-base-100 rounded-lg p-6 w-96 border border-white/30 shadow-lg">
      <h3 class="text-lg font-bold mb-2">Layout Changed</h3>
      <p class="text-sm opacity-75 mb-4">
        Your current layout has changed. Do you want to save before switching views?
      </p>

      <div class="flex gap-2 justify-end">
        <button class="btn btn-ghost btn-sm" @click="discardAndSwitch">
          Discard
        </button>
        <button class="btn btn-warning btn-sm" @click="saveAndSwitch">
          Save & Switch
        </button>
        <button class="btn btn-primary btn-sm" @click="cancelSwitch">
          Cancel
        </button>
      </div>
    </div>
  </div>
</template>

<script>
export default {
  data() {
    return {
      showSaveAsDialog: false,
      showLayoutConfirmation: false,
      saveAsName: '',
      saveAsError: null,
      pendingViewSwitch: null
    }
  },
  computed: {
    views() {
      return this.$storex.views.views || []
    },
    currentViewName() {
      return this.$storex.views.currentViewName
    },
    isProjectAdmin() {
      return this.$storex.projects.activeProject?.permissions?.includes('admin') ||
        this.$storex.session.user?.role === 'admin'
    }
  },
  methods: {
    openCreate() {
      this.$storex.ui.openViewEditor(null)
    },
    openEdit(view) {
      this.$storex.ui.openViewEditor(view)
    },
    openSaveAsDialog() {
      this.showSaveAsDialog = true
      this.saveAsName = ''
      this.saveAsError = null
      this.$nextTick(() => {
        this.$refs.saveAsInput?.focus()
      })
    },
    closeSaveAsDialog() {
      this.showSaveAsDialog = false
      this.saveAsName = ''
      this.saveAsError = null
    },
    async confirmSaveAs() {
      const name = this.saveAsName.trim()
      if (!name) {
        this.saveAsError = 'View name is required'
        return
      }
      if (this.views.find(v => v.name === name)) {
        this.saveAsError = 'A view with this name already exists'
        return
      }
      try {
        await this.$storex.views.saveView(name)
        this.$storex.ui.addNotification({ text: `View saved as "${name}"`, type: 'success' })
        this.closeSaveAsDialog()
      } catch (error) {
        this.saveAsError = error.message || 'Failed to save view'
      }
    },
    async updateCurrentView() {
      if (!this.currentViewName) return
      try {
        await this.$storex.views.saveView(this.currentViewName)
        this.$storex.ui.addNotification({ text: `View "${this.currentViewName}" updated`, type: 'success' })
      } catch (error) {
        this.$storex.ui.addNotification({ text: 'Failed to update view', type: 'error' })
      }
    },
    async switchToView(view) {
      // Check if layout has changed
      if (await this.$storex.views.hasLayoutChanged()) {
        this.pendingViewSwitch = view
        this.showLayoutConfirmation = true
      } else {
        await this.$storex.views.loadView(view)
      }
    },
    async saveAndSwitch() {
      if (this.currentViewName) {
        try {
          await this.$storex.views.saveView(this.currentViewName)
        } catch (error) {
          console.error('Failed to save before switch:', error)
        }
      }
      this.discardAndSwitch()
    },
    async discardAndSwitch() {
      if (this.pendingViewSwitch) {
        await this.$storex.views.loadView(this.pendingViewSwitch)
      }
      this.cancelSwitch()
    },
    cancelSwitch() {
      this.showLayoutConfirmation = false
      this.pendingViewSwitch = null
    },
    async deleteView(name) {
      if (confirm(`Are you sure you want to delete view "${name}"?`)) {
        try {
          await this.$storex.views.deleteView(name)
          this.$storex.ui.addNotification({ text: `View "${name}" deleted`, type: 'success' })
        } catch (error) {
          this.$storex.ui.addNotification({ text: 'Failed to delete view', type: 'error' })
        }
      }
    }
  }
}
</script>
