```js src/store/views.js
import { getterTree, mutationTree, actionTree } from 'typed-vuex'
import { $storex } from '.'
import { API } from '../api/api'

export const namespaced = true

export const state = () => ({
  views: [],
  currentView: {},
  lastView: null,
  lastSavedLayout: null
})

export const getters = getterTree(state, {
  viewNames: state => state.views.map(v => v.name),
  hasViews: state => state.views.length > 0,
  currentViewName: state => state.currentView?.name || null
})

export const mutations = mutationTree(state, {
  setViews(state, views) {
    state.views = views || []
  },
  setCurrentView(state, view) {
    state.currentView = view || {}
  },
  setLastView(state, view) {
    state.lastView = view || null
  },
  setLastSavedLayout(state, layout) {
    state.lastSavedLayout = layout ? JSON.parse(JSON.stringify(layout)) : null
  },
  addView(state, view) {
    if (!state.views.find(v => v.name === view.name)) {
      state.views.push(view)
    }
  },
  updateView(state, view) {
    const index = state.views.findIndex(v => v.name === view.name)
    if (index >= 0) {
      state.views[index] = view
    }
  },
  removeView(state, viewName) {
    state.views = state.views.filter(v => v.name !== viewName)
  }
})

export const actions = actionTree(
  { state, getters, mutations },
  {
    async init() {
      await $storex.views.loadViews()
    },

    async loadViews() {
      try {
        const views = await API.views.list()
        $storex.views.setViews(views)
      } catch (error) {
        console.error('Failed to load views:', error)
        $storex.views.setViews([])
      }
    },

    async saveView(_, viewName) {
      try {
        const layout = $storex.ui._desktopApi?.toJSON()
        if (!layout) {
          throw new Error('No layout to save')
        }
        const view = {
          name: viewName,
          layout: layout
        }
        await API.views.save(view)
        $storex.views.addView(view)
        $storex.views.setLastView(view)
        $storex.views.setLastSavedLayout(layout)
      } catch (error) {
        console.error('Failed to save view:', error)
        throw error
      }
    },

    async loadView(_, view) {
      try {
        $storex.views.setCurrentView(view)
        $storex.views.setLastView(view)
        if (view.layout && $storex.ui._desktopApi) {
          $storex.ui._desktopApi.fromJSON(view.layout)
        }
        // Store layout as last saved to detect future changes
        $storex.views.setLastSavedLayout(view.layout)
      } catch (error) {
        console.error('Failed to load view:', error)
        throw error
      }
    },

    async deleteView(_, viewName) {
      try {
        await API.views.delete(viewName)
        $storex.views.removeView(viewName)
        if (state.currentView?.name === viewName) {
          $storex.views.setCurrentView({})
          $storex.views.setLastSavedLayout(null)
        }
      } catch (error) {
        console.error('Failed to delete view:', error)
        throw error
      }
    },

    async renameView(_, { oldName, newName }) {
      try {
        await API.views.rename(oldName, newName)
        const view = state.views.find(v => v.name === oldName)
        if (view) {
          view.name = newName
          $storex.views.updateView(view)
          if (state.currentView?.name === oldName) {
            $storex.views.setCurrentView(view)
          }
          if (state.lastView?.name === oldName) {
            $storex.views.setLastView(view)
          }
        }
      } catch (error) {
        console.error('Failed to rename view:', error)
        throw error
      }
    },

    async loadViewForProject(_, projectId) {
      try {
        await $storex.views.loadViews()
        const lastView = state.lastView
        if (lastView && state.views.find(v => v.name === lastView.name)) {
          await $storex.views.loadView(lastView)
        }
      } catch (error) {
        console.error('Failed to load view for project:', error)
      }
    },

    // ADDED: Detect if current layout differs from last saved layout
    async hasLayoutChanged() {
      try {
        const currentLayout = $storex.ui._desktopApi?.toJSON()
        const lastLayout = state.lastSavedLayout

        if (!currentLayout || !lastLayout) {
          return false
        }

        const currentStr = JSON.stringify(currentLayout)
        const lastStr = JSON.stringify(lastLayout)
        return currentStr !== lastStr
      } catch (error) {
        console.error('Error checking layout changes:', error)
        return false
      }
    }
  }
)
